#!/bin/bash
# Task body for the 3-seed repeat-variant training runs (robustness check
# on the 4 main group A/B transfer variants). Portable: called by
# repeat_variant_array.sh (SLURM) and run_local.sh train_repeat <n>.
#
# Requires: ROOT, DEVICE set, SLURM_ARRAY_TASK_ID is a 1-based line number
# into repeat_variant_tasks.txt (generated by generate_task_lists.sh).
set -euo pipefail

TASKS_FILE="$ROOT/repeat_variant_tasks.txt"
LINE=$(sed -n "${SLURM_ARRAY_TASK_ID}p" "$TASKS_FILE")
if [ -z "$LINE" ]; then
    echo "train_repeat.sh: no line ${SLURM_ARRAY_TASK_ID} in $TASKS_FILE" >&2
    exit 1
fi
VARIANT=$(echo "$LINE" | cut -d, -f1)
DATA_PATH=$(echo "$LINE" | cut -d, -f2)
SEED=$(echo "$LINE" | cut -d, -f3)
RUN_NAME="${VARIANT}_seed${SEED}"

echo "[$(date +%T)] ${RUN_NAME} (data=${DATA_PATH}, seed=${SEED})"

uv run --project "$ROOT/ml" python3 "$ROOT/ml/main.py" train \
    --data_path "$ROOT/$DATA_PATH" \
    --ckpt_dir "$ROOT/results/checkpoints_repeats" \
    --context_len 150 \
    --no_cov \
    --augment \
    --epochs 50 \
    --early_stop 10 \
    --seed "$SEED" \
    --device "$DEVICE" \
    --run_name "$RUN_NAME"

echo "[$(date +%T)] Koniec: ${RUN_NAME}"
